// Generated by scripts/sync-help.mjs from pzza-code-web/components/docs/terminal/SearchShot.tsx. Regenerate with `npm run sync:help` rather than editing.
/**
 * Search terminals: the panel that searches every open terminal at once,
 * ported from the app's TerminalSearch (src/panels/TerminalSearch.tsx) with
 * its matching from src/terminal/terminalSearch.ts (compileQuery,
 * matchLines) run over the four sessions' captured screens: the active tile
 * first, then the rest in grid order, each match with the lines around it.
 * Typing searches again, the regex toggle switches to a regular expression,
 * and the arrows or the pointer move the current match.
 */
import { useId, useMemo, useState, type ReactNode } from "react";
import { Regex, Search, TextSearch } from "lucide-react";
import { CAPTURES } from "../../home/captures";
import { parseAnsi } from "../../home/ansi";
import type { SessionId } from "../../home/Scenes";
import { plainText, Viewport } from "./parts";
import { NARROW, WINDOW_BOX, WindowShot } from "./frames";

const QUERY = "newest";
// The grid's sessions in order, the api tile active (searched first).
const ORDER: SessionId[] = ["api", "web", "release", "docs"];

/* ------------------------------------------------ terminalSearch.ts port -- */

interface TerminalMatch {
  tileId: SessionId;
  /** 1-based logical line number in the terminal's buffer. */
  line: number;
  text: string;
  start: number;
  end: number;
  before: string;
  after: string;
}
interface TileMatches {
  tileId: SessionId;
  matches: TerminalMatch[];
  capped: boolean;
}

const MAX_TOTAL_MATCHES = 200;
const MAX_TILE_MATCHES = 50;
const CONTEXT_LENGTH = 240;
// Characters shown before the match on a long line (TerminalSearch.tsx, LEAD).
const LEAD = 48;

const escapeRegExp = (value: string) => value.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");

function compileQuery(query: string, regex: boolean): RegExp | null {
  if (!query) return null;
  try {
    return new RegExp(regex ? query : escapeRegExp(query), "gi");
  } catch (error) {
    throw new Error(error instanceof SyntaxError ? `Invalid regular expression: ${error.message.replace(/^Invalid regular expression: /, "")}` : "Invalid regular expression.");
  }
}

function clip(text: string): string {
  const trimmed = text.trimEnd();
  return trimmed.length > CONTEXT_LENGTH ? `${trimmed.slice(0, CONTEXT_LENGTH)}…` : trimmed;
}

function matchLines(tileId: SessionId, lines: string[], pattern: RegExp, limit: number): { matches: TerminalMatch[]; capped: boolean } {
  const matches: TerminalMatch[] = [];
  const re = new RegExp(pattern.source, pattern.flags);
  for (let index = 0; index < lines.length; index++) {
    const text = lines[index];
    re.lastIndex = 0;
    for (let found = re.exec(text); found; found = re.exec(text)) {
      if (!found[0].length) {
        re.lastIndex++;
        continue;
      }
      if (matches.length >= limit) return { matches, capped: true };
      matches.push({
        tileId,
        line: index + 1,
        text,
        start: found.index,
        end: found.index + found[0].length,
        before: index > 0 ? clip(lines[index - 1]) : "",
        after: index + 1 < lines.length ? clip(lines[index + 1]) : "",
      });
    }
  }
  return { matches, capped: false };
}

function searchTerminals(buffers: Record<SessionId, string[]>, pattern: RegExp): TileMatches[] {
  const groups: TileMatches[] = [];
  let total = 0;
  for (const tileId of ORDER) {
    const room = Math.min(MAX_TILE_MATCHES, MAX_TOTAL_MATCHES - total);
    const { matches, capped } = matchLines(tileId, buffers[tileId], pattern, room);
    if (matches.length) {
      groups.push({ tileId, matches, capped });
      total += matches.length;
    }
    if (total >= MAX_TOTAL_MATCHES) break;
  }
  return groups;
}

/* --------------------------------------------------------------- panel -- */

function MatchLine({ match }: { match: TerminalMatch }): ReactNode {
  const from = Math.max(0, match.start - LEAD);
  const head = (from > 0 ? "…" : "") + match.text.slice(from, match.start);
  const tail = match.text.slice(match.end, match.end + 200).trimEnd();
  return (
    <span className="term-search-line">
      {head}
      <mark>{match.text.slice(match.start, match.end)}</mark>
      {tail}
    </span>
  );
}

function TerminalSearch() {
  const listId = useId();
  const [query, setQuery] = useState(QUERY);
  const [regex, setRegex] = useState(false);
  const [cursor, setCursor] = useState(0);
  // Each terminal's buffer as logical lines: the captured screens' text.
  const buffers = useMemo(
    () => Object.fromEntries(ORDER.map((id) => [id, parseAnsi(CAPTURES[NARROW[id]]).map(plainText)])) as Record<SessionId, string[]>,
    [],
  );

  const result = useMemo((): { groups: TileMatches[]; error: string | null } => {
    try {
      const pattern = compileQuery(query.trim() ? query : "", regex);
      return { groups: pattern ? searchTerminals(buffers, pattern) : [], error: null };
    } catch (error) {
      return { groups: [], error: error instanceof Error ? error.message : "Invalid regular expression." };
    }
  }, [buffers, query, regex]);

  const rows = result.groups.flatMap((group) => group.matches);
  const current = rows.length ? rows[Math.min(cursor, rows.length - 1)] : undefined;
  const optionId = (match: TerminalMatch) => `${listId}-${rows.indexOf(match)}`;
  const move = (step: number) => {
    if (rows.length) setCursor((index) => (Math.min(index, rows.length - 1) + step + rows.length) % rows.length);
  };
  const total = rows.length;
  const capped = total >= MAX_TOTAL_MATCHES || result.groups.some((group) => group.capped);
  const status =
    result.error ??
    (!query.trim()
      ? "Type to search the scrollback of every open terminal."
      : total
        ? `${total} match${total === 1 ? "" : "es"} in ${result.groups.length} terminal${result.groups.length === 1 ? "" : "s"}${capped ? ", showing the first ones" : ""}`
        : "");

  return (
    <div className="modal-backdrop pzza-portal cmdk-backdrop">
      <div className="cmdk term-search" role="dialog" aria-modal="true" aria-label="Search all terminals" tabIndex={-1}>
        <div className="cmdk-search">
          <TextSearch size={16} strokeWidth={1.9} aria-hidden="true" />
          <input
            className="cmdk-input"
            value={query}
            placeholder="Search every terminal"
            spellCheck={false}
            autoComplete="off"
            role="combobox"
            aria-expanded="true"
            aria-controls={listId}
            aria-autocomplete="list"
            aria-label="Search terminal output"
            aria-activedescendant={current ? optionId(current) : undefined}
            onChange={(event) => {
              setQuery(event.target.value);
              setCursor(0);
            }}
            onKeyDown={(event) => {
              if (event.nativeEvent.isComposing) return;
              if (event.key === "ArrowDown" || event.key === "ArrowUp") {
                event.preventDefault();
                move(event.key === "ArrowDown" ? 1 : -1);
              } else if (event.key === "Enter") event.preventDefault();
            }}
          />
          <button
            type="button"
            className={`tile-btn ${regex ? "tile-btn-on" : ""}`}
            aria-pressed={regex}
            aria-label="Regular expression"
            title={regex ? "Regular expression on" : "Regular expression off"}
            onClick={() => {
              setRegex((value) => !value);
              setCursor(0);
            }}
          >
            <Regex size={14} aria-hidden="true" />
          </button>
          <kbd className="kbd" aria-hidden="true">
            ⇧⌘F
          </kbd>
        </div>
        <div className="cmdk-list term-search-list" id={listId} role="listbox" aria-label="Matches">
          {result.groups.map((group) => (
            <div className="cmdk-group" role="group" aria-label={group.tileId} key={group.tileId}>
              <div className="cmdk-group-title term-search-group" aria-hidden="true">
                <span>{group.tileId}</span>
                <span>
                  {group.matches.length}
                  {group.capped ? "+" : ""}
                </span>
              </div>
              {group.matches.map((match) => {
                const selected = match === current;
                return (
                  <div
                    key={`${match.line}:${match.start}`}
                    id={optionId(match)}
                    role="option"
                    aria-selected={selected}
                    className={`cmdk-row term-search-row ${selected ? "cmdk-row-active" : ""}`}
                    onMouseMove={() => {
                      if (!selected) setCursor(rows.indexOf(match));
                    }}
                    onMouseDown={(event) => event.preventDefault()}
                  >
                    <span className="term-search-number" aria-label={`Line ${match.line}`}>
                      {match.line}
                    </span>
                    <span className="term-search-context">
                      {match.before.trim() ? <span className="term-search-near">{match.before}</span> : null}
                      <MatchLine match={match} />
                      {match.after.trim() ? <span className="term-search-near">{match.after}</span> : null}
                    </span>
                  </div>
                );
              })}
            </div>
          ))}
          {query.trim() && !result.error && !total ? (
            <div className="cmdk-empty" role="status">
              <Search size={15} aria-hidden="true" />
              <span>No terminal output matches “{query.trim()}”.</span>
            </div>
          ) : null}
        </div>
        <div className="cmdk-foot term-search-foot">
          <span className={result.error ? "term-search-error" : ""} role={result.error ? "alert" : "status"}>
            {status}
          </span>
          <span aria-hidden="true">
            <kbd className="kbd">↵</kbd> jump
          </span>
          <span aria-hidden="true">
            <kbd className="kbd">esc</kbd> close
          </span>
        </div>
      </div>
    </div>
  );
}

export function SearchShot() {
  return (
    <WindowShot
      backdrop="palette"
      overlay={
        <Viewport width={WINDOW_BOX.width} height={WINDOW_BOX.height} z={100}>
          <TerminalSearch />
        </Viewport>
      }
    />
  );
}
